export class DomainError extends Error { constructor(public status:number,public code:string,message:string){ super(message);this.name='DomainError'; } }
const fail=(status:number,code:string,message:string):never=>{throw new DomainError(status,code,message);};
export function canonical(value:unknown):string { if(Array.isArray(value))return '['+value.map(canonical).join(',')+']'; if(value!==null&&typeof value==='object')return '{'+Object.entries(value).filter(([,v])=>v!==undefined).sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>JSON.stringify(k)+':'+canonical(v)).join(',')+'}';return JSON.stringify(value); }
export const hashPayload=(value:unknown)=>createHash('sha256').update(canonical(value)).digest('hex');
export const safeCsvCell=(value:unknown)=>{const text=String(value??'');return /^[\s]*[=+@\-\t\r]/.test(text)?"'"+text:text;};
const D=(v:unknown)=>new Decimal(String(v??'0'));
const sum=(values:unknown[])=>values.reduce<Decimal>((n,v)=>n.plus(D(v)),new Decimal(0));
