const customers=['customer_admin','receiver','customer_finance'];
const final=(p:Pod)=>p.status==='accepted'||p.status==='accepted_with_exceptions'||p.status==='refused';
const requireRole=(ctx:Context,roles:string[])=>{if(!roles.includes(ctx.role))fail(403,'FORBIDDEN','Your role cannot perform this action');};
const requireValue=async<T extends Entity>(tx:Transaction,kind:string,id:string):Promise<T>=>{const v=await tx.get<T>(kind,id);if(!v)fail(404,'NOT_FOUND','Record was not found');return v!;};
/** Complete matching history for invariants and sealed snapshots, read in bounded keyset pages. */
async function allMatching<T extends Entity>(tx:Transaction,kind:string,where:Record<string,unknown>):Promise<T[]>{
 const records:T[]=[];let cursor:string|undefined;
 do{const page=await tx.page<T>(kind,{where,limit:500,cursor});records.push(...page.items);cursor=page.nextCursor;}while(cursor);
 return records;
}
