export interface WorkflowOptions {validateReceiver?:(ctx:Context,input:{userId:string;organizationId:string;facilityId:string;contact:string},tx:Transaction)=>Promise<void>;otpSecret?:string;deliverOtp?:(contact:string,code:string)=>Promise<void|{reference:string}>;now?:()=>Date}
