  const a=await requireValue<Attempt>(tx,'attempts',pod.attemptId);this.requireAttemptScope(ctx,a);const now=this.timestamp();
  const policy=await this.policy(tx,c),all=await tx.list<ReceiverGrant>('grants');const grants=all.filter(g=>g.userId===ctx.userId&&g.organizationId===c.consigneeId&&g.facilityId===a.facilityId&&g.action==='accept_pod'&&!g.revokedAt&&g.validFrom<=now&&g.validUntil>now&&(!g.consignmentId||g.consignmentId===c.id)&&(policy.receiverScope!=='consignment'||g.consignmentId===c.id)&&(!g.delegatesGrantId||all.some(parent=>parent.id===g.delegatesGrantId&&!parent.revokedAt&&parent.validFrom<=now&&parent.validUntil>now))).sort((a,b)=>a.id.localeCompare(b.id));
