  const facilitySnapshot=identity(await requireValue(tx,'facilities',attempt.facilityId)),consignorSnapshot=identity(await requireValue(tx,'organizations',c.consignorId)),consigneeSnapshot=identity(await requireValue(tx,'organizations',c.consigneeId)),payerSnapshot=identity(await requireValue(tx,'organizations',c.payerId));
